import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Universal Actions for Enhanced Embodied Foundation Models","description":"","frontmatter":{"title":"Universal Actions for Enhanced Embodied Foundation Models","arxiv":"2501.10105","date":"2025-01-17","authors":"Jinliang Zheng, Jianxiong Li, Dongxiu Liu, Yinan Zheng, Zhihao Wang, Zhonghong Ou, Yu Liu, Jingjing Liu, Ya-Qin Zhang, Xianyuan Zhan","categories":"cs.RO, cs.AI, cs.CV","topics":"具身智能, 跨形态迁移, 通用动作空间","outline":[2,2]},"headers":[],"relativePath":"papers/2501.10105.md","filePath":"papers/2501.10105.md","lastUpdated":null}'),l={name:"papers/2501.10105.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="universal-actions-for-enhanced-embodied-foundation-models" tabindex="-1">Universal Actions for Enhanced Embodied Foundation Models <a class="header-anchor" href="#universal-actions-for-enhanced-embodied-foundation-models" aria-label="Permalink to &quot;Universal Actions for Enhanced Embodied Foundation Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2501.10105" target="_blank" rel="noreferrer">2501.10105</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-01-17</td></tr><tr><td><strong>作者</strong></td><td>Jinliang Zheng, Jianxiong Li, Dongxiu Liu, Yinan Zheng, Zhihao Wang, Zhonghong Ou, Yu Liu, Jingjing Liu, Ya-Qin Zhang, Xianyuan Zhan</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 VLM 在 256 项向量量化码本上做&quot;选哪个原子行为&quot;的分类，把异构动作空间收缩成一个共享瓶颈，再用各机器人一个轻量 MLP 头解回具体控制信号。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>跨机构众包的机器人数据在动作层面是割裂的。同样是&quot;向前移动&quot;这个行为，7-DoF 机械臂用末端位置增量表达，四足用关节角表达，小车用二维速度表达；即便同为机械臂，有的数据集记录末端绝对位置，有的记录末端速度，有的记录关节位置；即便同一台机器人，不同人类操作者的行为多模态也会让轨迹分布分裂。结果是不同来源的动作数据落在原始物理空间中几乎不相交的流形上。</p><p>论文要解决的问题是：如何让这些数据真正共享，而不是被强行对齐。这个问题重要，因为 embodied foundation model 的整套论证都建立在&quot;数据越多越好&quot;之上，而当前所有大规模机器人数据集加起来的规模仍远小于 LLM 的语料。如果异构性导致每加入一个新数据源就带来负迁移，那么规模化这条路在起点就被堵死了。论文给出的一个直接证据是：CrossFormer 用了比 Octo 更多样的预训练数据，但在 WidowX 上的表现反而不如它的代码基座 Octo，作者推测原因是把所有单臂机器人不分控制接口一律当作同一种 embodiment，诱发了负迁移。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>第一类是无视异构性。RT-X、Octo、OpenVLA 把不同 7-DoF 机器人的动作强行用同一套离散化或归一化处理。它们确实证明了多机器人数据比单机器人数据泛化更好，但代价是同一个动作编码在不同数据源里可能代表完全不同的物理含义，形成冲突的动作空间。</p><p>第二类是把所有动作空间朴素堆叠。CrossFormer、RDT、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、Yang 等人的工作把机械臂、导航、单臂、双臂的动作空间拼在一起，为每种形态留出对应的输出维度。这条路需要大量人工工程，而且它只做了&quot;并集&quot;，没有去挖掘不同动作空间之间的内在联系——共性被表示成了并列而非共享。</p><p>第三类是从无动作视频里学 latent action。LAPA、IGOR、LAPO 联合训练逆动力学与正动力学模型，用两帧之间的视觉变化定义 latent action。论文精确地指出了两个问题：一是观测变化不只包含机器人的动作后果，还包含与控制无因果关系的外部因素（有人往桌上放了个新物体，画面变了但机器人什么都没做）；二是两帧之间的时间间隔直接决定了抽出的&quot;原子行为&quot;的语义粒度，跨数据源标准化这个粒度很麻烦。</p><p>第四类是离散动作码本。BeT、VQ-BeT、QueST 用 K-means 或 VQ 建码本，每个码代表一个动作聚类中心。它们主要处理单一 embodiment 下人类演示的多模态问题，码本编码的是原始动作标签的聚类，跨 embodiment 时聚类中心本身就没有共同含义。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个纯直觉的观察：面对正前方的目标，不同机器人都应该做出&quot;向前移动&quot;这个行为，尽管它们的控制信号因为 embodiment 差异完全不同。这说明行为层面存在共性，只是被控制接口的细节掩盖了。</p><p>于是问题变成：怎么把这个共性提取出来？最自然的想法是学一个 latent 空间，但直接从视觉变化学（LAPA 那条路）会把无关的场景变化也编码进去。这里的关键一步是换一个监督信号：不要问&quot;两帧之间画面变了什么&quot;，而要问&quot;为了推进这个任务，现在该做什么&quot;。前者的因果链是&quot;动作 → 观测变化&quot;，中间混入大量外部噪声；后者的因果链是&quot;任务目标 + 当前观测 → 该做的行为&quot;，直接锚定在任务进展上。</p><p>一旦确定要预测&quot;该做什么&quot;，用 VLM 做这个推断就是自然选择——它本来就擅长视觉语言推理，而且预训练权重能大幅提升样本效率。接着需要一个机制强制不同机器人共享表示，否则模型可以为每个数据源学一套独立的隐变量。信息瓶颈是标准答案：把输出限制在一个固定大小的离散码本上，所有机器人被迫用同一批码来描述自己的行为。</p><p>最后是解码。既然共性已经在码本里，那么从通用动作回到具体控制信号所需要补充的就只是 embodiment 细节，这部分应该很轻。轻还有一个额外好处——如果解码头参数很多，它会自己把任务学掉，让码本退化成无意义的中间变量；保持解码头简单，才能逼迫学习集中在通用动作上。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不同机器人的控制信号不可比，但它们试图完成的原子行为可比。把 VLM 的输出限制成&quot;从 256 个通用动作里选一个&quot;，这个窄瓶颈逼着所有机器人用同一套词汇描述自己在做什么，embodiment 差异被挤到瓶颈之外，由各自的轻量解码头单独承担。共性一旦被学到，接一个新机器人就只是训一个小 MLP 的事。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以真实 WidowX 上执行&quot;把茄子放进锅里&quot;为例。</p><ul><li><strong>通用动作空间</strong>：一个向量量化码本 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">256</span><span class="mbin mtight">×</span><span class="mord mtight">128</span></span></span></span></span></span></span></span></span></span></span></span>，即 256 个 128 维向量，每个代表一个通用原子行为。可以理解成一个可学习的技能库。</li><li><strong>提取器</strong>：基于 LLaVA-OneVision-0.5B 微调，输入第三人称图像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">o</span></span></span></span> 与语言指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>，输出在 256 个码上的分布 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span>。因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span></span></span></span> 不可导，训练时用 Gumbel-Softmax 做类别重参数化，并随训练逐步衰减温度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>，早期鼓励探索、后期稳定收敛。</li><li><strong>异构解码</strong>：每个训练域一个头 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，都是简单 MLP，输入是选中的通用动作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span> 与一个 ImageNet 预训练 ResNet-18（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span>）抽的视觉特征，输出该 embodiment 的控制信号 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.888em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span></span></span></span>。VLM 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">384</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">384</span></span></span></span> 分辨率。</li><li><strong>训练</strong>：1M 条演示、28 种 embodiment，数据来自 Open-X Embodiment、LIBERO、DROID，统一成第三人称视角加语言指令但<strong>保留动作异构性</strong>——不做 OpenVLA 那样把绝对末端位置转成相对、把关节位置数据删掉的清洗。码本与提取器每步都更新，各解码头只在采到本域 batch 时更新，作者类比 meta-learning 里全局共享参数加任务特定组件的思路。64 张 A100 跑 10 天，batch 1024，AdamW，500K 步。</li><li><strong>部署到新机器人</strong>：冻结码本与提取器，为新的控制接口从头训一个 MLP 头。在 AIRBOT 上只需 100 条演示、4 张 A100 训 1 小时，可训参数 4M / 500M，占比 0.8%。</li></ul><p>一个实用的副产品：因为每个通用动作对应一个语义清晰的行为，人可以直接按 ID 序列手动操控机器人完成 pick &amp; place，不需要懂正逆运动学。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>通用动作空间定义为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span>，每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6891em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">128</span></span></span></span></span></span></span></span></span></span></span></span>。理想的选择是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7387em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.5217em;vertical-align:-0.7717em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">u</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0993em;">U</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7717em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span></span></p><p>这个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span></span></span></span> 是硬选择，梯度无法回传。Gumbel-Softmax 的做法是把硬采样松弛成加权平均：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7387em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.9291em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6514em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.421em;vertical-align:-0.994em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.3057em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8043em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mopen">(</span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mopen">(</span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.994em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 Gumbel 分布采样的噪声。直觉上，加 Gumbel 噪声再取 softmax 等价于从类别分布中采样（Gumbel-max trick），温度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span></span></span></span> 趋近 one-hot 恢复硬选择，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 大时接近均匀分布。训练中逐步降温，就是从&quot;软探索所有码&quot;平滑过渡到&quot;确定性选一个码&quot;。</p><p>总目标是所有域的行为克隆损失之和：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:3.1304em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0993em;">U</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8882em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:-0.1132em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mspace mtight" style="margin-right:0.1952em;"></span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:-0.1132em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size2">[</span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mclose mtight">)</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.0448em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.2198em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size2">]</span></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 按各数据集动作标签的性质定制：离散动作用 Cross-Entropy，连续动作用 MSE、Huber 或 diffusion loss。注意这里没有 VQ-VAE 常见的 commitment loss 与 codebook loss——码本是通过 Gumbel-Softmax 的加权和直接接收梯度的。</p><p>有一个值得记的负面结果：作者也试过 Straight-Through Estimator，结果码本严重塌缩。给出的解释是每个通用动作需要大量优化步才能学到高度抽象的行为，而 STE 是硬采样，每个训练样本只有一个码被选中并优化，梯度无法分配到其他候选码上，学习被扼制、多样性下降。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>通用动作能否提升跨形态执行？</strong> 在真实 WidowX 与仿真 Franka（LIBERO）上做 out-of-the-box 评测。WidowX 覆盖 19 个任务、每任务 10 次、共 190 次 rollout，分五个维度。逐维度平均分：视觉泛化 UniAct-0.5B 6.8 对 OpenVLA 6.6 对 Octo 2.4；运动泛化 6.0 对 3.5 对 3.0；物理泛化 7.0 对 6.0 对 1.0。这三项 UniAct 都领先。语义泛化 3.9 对 4.8 对 1.9，语言 grounding 7.3 对 8.8 对 4.8，这两项 OpenVLA 靠 7B 骨干占优，UniAct 用 0.5B 做到可比。LIBERO 的 130 个任务、五个 suite 上，UniAct 全面超过基线。</p><p><strong>能否快速适配未见机器人？</strong> AIRBOT 是预训练完全没见过的真实机器人，任务是把小方块叠到小长方体上，需要精确执行。测试四种控制接口：相对/绝对的末端位置与关节位置。UniAct 在四种接口上都稳定超过 OpenVLA 与 Octo，而微调参数占比最小（0.8% 对 OpenVLA 的 1.4%、Octo 的 2%）。评测还包含一个 hard 版本，微调数据不含干扰物但测试时加入杂乱物体。</p><p><strong>能否换更强的解码头？</strong> 冻结 UniAct-0.5B，接 ACT 头适配双臂 AIRBOT，用顶视加两路腕部视角加本体感知，每任务 250 条演示。四个任务上 UniAct 对未经具身预训练的 LLaVA-OV-0.5B：扫盘子 45 对 7.5，叠毛巾 62.5 对 20，放杯子 50 对 2.5，运笔 65 对 15。在 LIBERO 上换 ACT 头也进一步提升。</p><p><strong>码本是否真的通用？</strong> 两个证据。一是人工检查全部 256 个通用动作在不同机器人上解码出的行为，至少 40% 表现出完全一致的语义，即便跨视角、跨真实与仿真。二是统计通用动作的使用分布，用 JS 散度衡量：同一任务跨机器人（WidowX 与 Franka 的&quot;pick up the bowl&quot;）散度 0.34，同一机器人跨任务（&quot;pick up the bowl&quot;与&quot;open the drawer&quot;）散度 0.44 到 0.60。同任务跨机器人比同机器人跨任务更相似，说明提取器确实抓住了与 embodiment 无关的行为。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：跨机构机器人数据的动作空间因 embodiment 与控制接口不同而互不相容，现有做法要么强行等同要么朴素并集，都无法利用共性。UniAct 把 VLM 的输出限制在 256 项向量量化码本上，用 Gumbel-Softmax 让&quot;选哪个原子行为&quot;可导，形成一个强制跨域共享的信息瓶颈。每个机器人只用一个轻量 MLP 头把通用动作加上自身细节解回控制信号，训练时保留原始动作异构性、不做数据清洗。0.5B 的实例在真实 WidowX 的视觉、运动、物理泛化上超过 14 倍大的 OpenVLA-7B，在 LIBERO 全部五个 suite 上领先，适配未见机器人只需 100 条演示、4M 参数、1 小时。JS 散度分析显示同任务跨机器人的码使用分布比同机器人跨任务更相似，证明码本编码的是行为而非 embodiment。</p><p><strong>3 句话版</strong>：把&quot;该做什么行为&quot;而不是&quot;画面变了什么&quot;作为 latent action 的监督信号，再用离散码本当跨域瓶颈。0.5B 模型在多数泛化维度上超过 7B 的 OpenVLA，新机器人适配只需训一个 4M 的 MLP 头。至少 40% 的码在不同机器人上解出语义一致的行为。</p><p><strong>1 句话版</strong>：把动作异构性从模型主干推到最后一层 MLP，共性就能被 256 个离散码学到。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>不同 embodiment 的行为共性可以被一个固定大小的离散码本充分表达</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span> 是一个硬性容量上限，如果真实的行为空间需要更多互不相同的原子行为，码本就会被迫用同一个码表示不同行为，解码头必须靠视觉特征把它们区分开——一旦解码头承担了这个区分任务，通用动作就退化成了一个近似无信息的条件变量，整套 claim 崩塌。</p><p>论文自己的数据给了这个担忧一个直接支点：人工检查只有&quot;至少 40%&quot;的码在不同机器人上语义一致。剩下不到 60% 是什么状态，论文没说。这个数字如果理解为&quot;多数码并不通用&quot;，那么解码头到底承担了多少工作就成了未验证的关键问题。而解码头的输入包含完整的 ResNet-18 视觉特征，理论上一个 MLP 完全可以主要依赖视觉信号来预测动作，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span> 当成一个弱先验。</p><p>论文在这一点上缺少最关键的一个消融：<strong>把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span> 替换成随机码或常量，只保留视觉特征训解码头</strong>。如果性能只下降一点，说明通用动作贡献有限。现有的正面证据（JS 散度、人工检查、快速适配）都是间接的——JS 散度只说明码使用分布与任务相关，不能说明解码时码起了多大作用；快速适配的收益也可能来自共享 ResNet 视觉骨干在 1M 条机器人数据上的预训练，而非码本本身。</p><p>论文明确承认的另一重限制是评测范围：所有实验基本都在单臂机械臂上，作者自己提出的疑问是&quot;物理运动的共性是否只存在于机械臂之间&quot;，并把四足、灵巧手、自动驾驶列为未来工作。双臂 AIRBOT 的实验用了 ACT 头而非简单 MLP，这<strong>可以推断</strong>为单靠 256 个码加 MLP 不足以覆盖双臂控制的复杂度。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要 64 张 A100：</p><ul><li><strong>数据</strong>：只用 LIBERO 的 130 个任务加 Bridge 的一个子集，人为制造异构性——把 LIBERO 的动作保持末端位置，把 Bridge 的一半轨迹转成末端速度表示，构成两到三个&quot;控制接口&quot;。</li><li><strong>实现</strong>：用 LLaVA-OneVision-0.5B 或更小的 VLM 做提取器，码本设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">64</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>（按数据规模等比缩小），Gumbel-Softmax 带温度退火，每个域一个两层 MLP 头。</li><li><strong>关键对照</strong>：训三个版本。(a) 完整 UniAct；(b) 把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span> 替换成固定常量向量，解码头只靠 ResNet 视觉特征；(c) 每个域一套独立码本（去掉共享瓶颈）。</li><li><strong>测量</strong>：三者在各域的成功率；对完整版统计码使用分布的 JS 散度（同任务跨域 vs 同域跨任务）；人工检查码的语义一致率。</li><li><strong>判据</strong>：如果 (a) 显著优于 (b)，证明通用动作确实携带了必要信息；如果 (a) 优于 (c)，证明共享瓶颈带来了正迁移而非负迁移。若 (b) 逼近 (a)，则核心 claim 被反驳——性能来自视觉骨干而非码本。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出一个<strong>替代解释</strong>：UniAct 的性能优势主要来自&quot;不清洗数据&quot;这一工程差异，而非通用动作空间本身。论文明确说基线模型的训练数据被清洗过（绝对末端位置转成相对、删掉关节位置动作），而 UniAct &quot;不采用这种繁琐的数据清洗&quot;。这意味着 UniAct 实际见到的数据比基线更多、更全。表 5 显示训练混合里 RoboSet 与 TOTO 用的是关节位置控制，采样率合计 7%，这部分数据基线根本没用上。同时论文指出手动清理 no-op 数据对 OpenVLA 在 LIBERO 上收敛&quot;至关重要&quot;，这暗示基线的数据管线本身很脆弱。</p><p>设计的反例实验：训一个<strong>同数据、无码本</strong>的对照——同样的 VLM 骨干、同样未清洗的 28 域数据、同样每域一个 MLP 头，但 VLM 输出连续隐向量而不经过离散码本。如果这个对照追平 UniAct，那么&quot;通用动作空间&quot;就不是关键，关键只是&quot;每个域一个轻量头 + 保留原始动作&quot;的多头架构。论文没有报告这个对照，而它恰恰是分离&quot;离散瓶颈&quot;与&quot;多头架构&quot;两个贡献的唯一方式。</p><p>第二类可预测失效：形态差异跨越运动学类别时。UniAct 的全部证据来自机械臂（WidowX、Franka、AIRBOT），它们共享&quot;末端在三维空间中移动加夹爪开合&quot;这一结构。把四足行走或灵巧手的手内操作加进来，&quot;向前移动&quot;在机械臂上是末端平移、在四足上是整体位移、在灵巧手上根本没有对应物。可以预测的现象是：加入这些形态后，码本会自发按形态类别分区（机械臂用一批码、四足用另一批），共享率下降，退化成带软路由的多任务模型。设计一个实验：把 GO-1 类四足导航数据混入训练，重新统计跨形态的码使用 JS 散度，若从 0.34 大幅上升，则通用性的边界被定量刻画出来。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：码本大小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span> 是一个人为设定的常数，与 embodiment 数量、任务多样性、数据规模都无关。论文自己在 limitation 里承认解码头的复杂度&quot;应该按各 embodiment 的控制复杂度定制&quot;，但对码本容量没有对应的讨论。这暴露了一个结构性问题：UniAct 用一个平坦的、无结构的码本承载所有共性，既没有表达&quot;某些行为只在部分形态间共享&quot;的能力，也没有随规模自适应的机制。</p><p><strong>新 framing</strong>：把通用动作空间从&quot;平坦码本&quot;重构成<strong>带偏序结构的行为层级</strong>。核心 framing 转变是承认共性不是二元的，而是分层的：最顶层是所有 embodiment 共享的行为（趋近目标、抓握、释放），中层是运动学类别内共享的（机械臂的末端旋转、腿式的步态相位），底层是形态特有的。用残差量化（residual quantization）表达这个层级——第一级码捕捉最普适的行为，后续级别逐步补充形态特定的细节，每个 embodiment 按自身复杂度决定用几级。这不是&quot;扩大码本&quot;，而是让共性的<strong>粒度本身成为可学习的结构</strong>，同时天然回答了 §9 提出的容量问题与 §11 预测的形态分区问题：分区会自动出现在残差的第二级而非污染第一级。</p><p><strong>可借鉴的相邻领域工具</strong>：音频编解码里的 SoundStream 与 Encodec 用残差向量量化把波形分解成粗到细的多级码，第一级承载语音内容、后续级承载音色与细节，这与&quot;行为共性分层&quot;的结构完全同构；层级强化学习里的 options 框架提供了刻画&quot;不同抽象层级的时序策略&quot;的形式化语言；生物运动控制中的 motor primitives 假说也支持行为按层级组织的先验。</p><p><strong>第一个实验</strong>：不必重训 1M 数据。取 UniAct 已训好的模型，在包含机械臂（Bridge）、移动操作（CMU Stretch）、以及一个新引入的腿式或双臂数据源的三方混合上，训练一个两级残差码本版本（第一级 64 码共享给全部形态，第二级 64 码可按形态分组）。测量两件事：一是第一级码在三类形态间的使用分布 JS 散度是否低于原始单级码本的 0.34；二是人工检查第一级码的跨形态语义一致率能否从 40% 提升到 70% 以上。如果两项都成立，说明分层结构确实把&quot;真正通用&quot;的行为从&quot;形态特定&quot;的行为里分离了出来，那么再考虑全量重训与更多形态的扩展。</p>',58)])])}const u=a(l,[["render",e]]);export{o as __pageData,u as default};
